<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import * as api from '@/api/wall'
import {useAuthStore} from '@/stores/auth'
import {useWallStore} from '@/stores/wall'
import {errorMessage} from '@/api/identity'
import type {AdminWallRow,AdminWallDetail,AdminWallComment,ModerationTarget,WallReport} from '@/wall/types'
import WallComposer from '@/components/wall/WallComposer.vue'
import WallModerationForm from '@/components/wall/WallModerationForm.vue'
import WallFormattedText from '@/components/wall/WallFormattedText.vue'
import '@/styles/wall.css'
const auth=useAuthStore(),wall=useWallStore(),rows=ref<AdminWallRow[]>([]),status=ref(''),flagged=ref(false),cursor=ref<string|null>(null),more=ref(false),busy=ref(false),error=ref(''),announcing=ref(false),editing=ref(false),target=ref<ModerationTarget|null>(null),selected=ref<AdminWallDetail|null>(null),comments=ref<AdminWallComment[]>([]),commentCursor=ref<string|null>(null),commentMore=ref(false),context=ref<HTMLDialogElement>(),checked=ref<string[]>([])
const labels:Record<string,string>={VISIBLE:'公开中',HIDDEN:'已隐藏',DELETED:'已删除'},actions:Record<string,string>={EDIT:'编辑',HIDE:'隐藏',RESTORE:'恢复展示',DELETE:'删除',KEEP:'处理举报并保留'}
let generation=0
async function load(reset=true){const g=++generation;busy.value=true;error.value='';if(reset){cursor.value=null;rows.value=[]}try{const page=await api.adminMessages({status:status.value,flagged:flagged.value,cursor:cursor.value??undefined});if(g!==generation)return;rows.value=reset?page.items:[...rows.value,...page.items.filter(r=>!rows.value.some(x=>x.message.id===r.message.id))];cursor.value=page.nextCursor;more.value=page.hasMore}catch(e){if(g===generation)error.value=errorMessage(e)}finally{if(g===generation)busy.value=false}}
watch(()=>auth.user?.id,key=>{wall.bindIdentity(key??'guest');selected.value=null;context.value?.close();editing.value=false;announcing.value=false;void load()},{immediate:true})
onBeforeUnmount(()=>generation++)
async function inspect(id:string){const g=++generation;busy.value=true;error.value='';try{const [detail,page]=await Promise.all([api.adminMessage(id),api.adminComments(id)]);if(g!==generation)return;selected.value=detail;comments.value=page.items;commentCursor.value=page.nextCursor;commentMore.value=page.hasMore;checked.value=[];context.value?.showModal()}catch(e){if(g===generation)error.value=errorMessage(e)}finally{if(g===generation)busy.value=false}}
async function moreComments(){if(!selected.value||!commentCursor.value)return;const g=generation;busy.value=true;try{const page=await api.adminComments(selected.value.message.id,commentCursor.value);if(g!==generation)return;comments.value.push(...page.items.filter(c=>!comments.value.some(x=>x.comment.id===c.comment.id)));commentCursor.value=page.nextCursor;commentMore.value=page.hasMore}catch(e){if(g===generation)error.value=errorMessage(e)}finally{if(g===generation)busy.value=false}}
function messageAction(row:AdminWallRow|AdminWallDetail,action:string){const m=row.message;const reports='reports'in row?row.reports:[];target.value={id:m.id,version:m.version,action,targetType:'MESSAGE',kind:m.kind,text:m.text,title:m.title,reportIds:reports.filter(r=>checked.value.includes(r.id)&&r.status==='PENDING').map(r=>r.id)};editing.value=true}
function commentAction(row:AdminWallComment,action:string){target.value={id:row.comment.id,version:row.comment.version,action,targetType:'COMMENT',text:row.comment.text,reportIds:row.reports.filter(r=>checked.value.includes(r.id)&&r.status==='PENDING').map(r=>r.id)};editing.value=true}
async function saved(){editing.value=false;context.value?.close();selected.value=null;await load()}
function pending(reports:WallReport[]){return reports.filter(r=>r.status==='PENDING')}
</script>
<template>
 <section class="wall-admin-page"><header class="wall-admin-heading"><div><h1>留言管理</h1><p>巡查留言与讨论，处理举报并告知作者。</p></div><div><RouterLink class="wall-admin-preview" to="/wall">查看留言墙</RouterLink><button class="button-primary" @click="announcing=true">＋ 发布公告便签</button></div></header>
 <div class="wall-admin-filters"><label>留言状态 <select v-model="status" @change="load()"><option value="">全部状态</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><label><input v-model="flagged" type="checkbox" @change="load()"> 仅待处理举报</label></div><p v-if="error" role="alert" class="wall-error">{{error}} <button :disabled="busy" @click="load()">重试</button></p><p v-if="busy" role="status" class="muted">正在加载…</p>
 <div class="wall-table-wrap"><table><thead><tr><th>留言内容</th><th>作者 / 状态</th><th>举报</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.message.id"><td><strong v-if="row.message.kind==='ANNOUNCEMENT'">公告 · {{row.message.title}}</strong><p class="wall-admin-excerpt">{{row.message.text}}</p><small>{{new Date(row.message.createdAt).toLocaleString('zh-CN')}}</small></td><td>{{row.message.author.displayName}}<span class="wall-status">{{labels[row.status]}}</span></td><td>{{row.pendingReports?'待处理 '+row.pendingReports:'无待处理'}}</td><td><button :disabled="busy" @click="inspect(row.message.id)">查看与处理举报</button><template v-if="row.status==='VISIBLE'"><button @click="messageAction(row,'EDIT')">编辑</button><button @click="messageAction(row,'HIDE')">隐藏</button><button class="wall-danger" @click="messageAction(row,'DELETE')">删除</button></template><template v-else-if="row.status==='HIDDEN'"><button @click="messageAction(row,'RESTORE')">恢复展示</button><button class="wall-danger" @click="messageAction(row,'DELETE')">删除</button></template></td></tr><tr v-if="!busy&&!rows.length"><td colspan="4">没有符合条件的留言。</td></tr></tbody></table></div><button v-if="more" :disabled="busy" @click="load(false)">加载更多留言</button>
 <WallComposer :open="announcing" announcement @close="announcing=false" @posted="announcing=false;load()"/><WallModerationForm :open="editing" :target="target" @close="editing=false" @saved="saved"/>
 <dialog ref="context" class="wall-dialog wall-admin-context" aria-labelledby="wall-context-title"><header class="wall-dialog-heading"><div><h2 id="wall-context-title">留言与讨论</h2><p class="muted">{{selected?.message.author.displayName}} · {{labels[selected?.status??'']}}</p></div><button aria-label="关闭管理上下文" @click="context?.close()">×</button></header><template v-if="selected"><h3 v-if="selected.message.title">{{selected.message.title}}</h3><p class="wall-detail-text"><WallFormattedText :text="selected.message.text" :announcement="selected.message.kind==='ANNOUNCEMENT'"/></p><section v-if="selected.reports.length" class="wall-report-list"><h3>留言举报</h3><label v-for="r in selected.reports" :key="r.id"><input v-if="r.status==='PENDING'" v-model="checked" type="checkbox" :value="r.id">{{r.reason}} · {{r.status==='PENDING'?'待处理':'已处理'}}<p>{{r.detail}}</p></label></section><div class="wall-detail-actions"><button v-if="selected.status==='VISIBLE'" @click="messageAction(selected,'EDIT')">编辑留言</button><button v-if="selected.status==='VISIBLE'" @click="messageAction(selected,'HIDE')">隐藏留言</button><button v-if="selected.status==='HIDDEN'" @click="messageAction(selected,'RESTORE')">恢复留言</button><button v-if="pending(selected.reports).length" @click="messageAction(selected,'KEEP')">处理选中举报并保留</button></div>
 <h3>讨论</h3><article v-for="row in comments" :key="row.comment.id" class="wall-reply"><header><span>{{row.comment.author.displayName}} · {{labels[row.status]}}</span></header><p>{{row.comment.text}}</p><label v-for="r in row.reports" :key="r.id" class="wall-report-label"><input v-if="r.status==='PENDING'" v-model="checked" type="checkbox" :value="r.id">{{r.reason}} · {{r.status==='PENDING'?'待处理':'已处理'}} · {{r.detail}}</label><div class="wall-detail-actions"><button v-if="row.status==='VISIBLE'" @click="commentAction(row,'HIDE')">隐藏评论</button><button v-if="row.status==='HIDDEN'" @click="commentAction(row,'RESTORE')">恢复评论</button><button v-if="row.status!=='DELETED'" class="wall-danger" @click="commentAction(row,'DELETE')">删除评论</button><button v-if="pending(row.reports).length" @click="commentAction(row,'KEEP')">处理评论举报并保留</button></div></article><button v-if="commentMore" :disabled="busy" @click="moreComments">加载更多评论</button>
 <details class="wall-audit"><summary>管理记录（仅管理员可见）</summary><article v-for="entry in selected.history" :key="entry.id"><h4>{{actions[entry.action]}} · {{new Date(entry.createdAt).toLocaleString('zh-CN')}}</h4><p>告知作者：{{entry.authorReason}}</p><p>内部备注：{{entry.internalNote||'无'}}</p><pre>原文：{{entry.beforeText}}
新文：{{entry.afterText}}</pre></article><p v-if="!selected.history.length">尚无处理记录。</p></details></template></dialog>
 </section>
</template>
